# Source dictionary keeps URLs and full descriptions in the package, not as printed back matter.
ledger=[]
for m in re.finditer(r'\\item\[(3\.[456]-[SE]\d+)\]\s*(.*?)(?=\\item\[|\\end\{description\})',old,re.S):
 ledger.append({'id':m[1],'description_tex':m[2].strip(),'urls':re.findall(r'\\href\{([^}]+)\}',m[2])})
base='https://github.com/X-lab2017/2026-Global-Open-Source-Development-Report/blob/c51e3441361407b68f10b339d97eff288319b503/data/processed/chapter3/'
for sec,pattern in [('3.1','s3.1/ch31_v02/data/*csv'),('3.2','s3.2/ch32_v03/data/*csv')]:
 files=sorted((R/'sources').glob(pattern))
 for f in files:
  num=int(re.search(r'(?:table|fig)-3-[12]-(\d+)',f.name)[1]);code=(num if f.name.startswith('table') else num+2)
  if sec=='3.1':code=num
  ledger.append({'id':sec+'-S'+str(code),'file':str(f.relative_to(R)),'urls':[base+f.name],'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
for code in range(1,5):
 # Original complete source paragraphs retained, with all links.
 mt=re.search(r'\\key\{3\.3-R'+str(code)+r'。\}(.*?)(?=\n\n)',old,re.S)
 txt=mt[1] if mt else ''
 urls=re.findall(r'\\href\{([^}]+)\}',txt)
 if code==1:urls=[base+f.name for f in (R/'sources/s3.3/GOSD_2026_3.3_v0.2/data').glob('*.csv') if f.name.startswith(('table-3-3-1','fig-3-3-1'))]
 ledger.append({'id':'3.3-R'+str(code),'description_tex':txt,'urls':urls})
# Some 3.5/3.6 source entries use topic paragraphs rather than description lists.
for sec,letter,count in [('3.5','E',5),('3.6','E',4)]:
 for i in range(1,count+1):
  sid=f'{sec}-{letter}{i}'
  if any(x['id']==sid for x in ledger):continue
  mt=re.search(r'\\(?:key|topic)\{'+re.escape(sid)+r'[^}]*\}(.*?)(?=\n\n)',old,re.S)
  txt=mt[1] if mt else ''
  ledger.append({'id':sid,'description_tex':txt,'urls':re.findall(r'\\href\{([^}]+)\}',txt)})
lookup={r['id']:r['urls'][0] for r in ledger if r['urls']}
def tex(s):
 return s.replace('&',r'\&').replace('%',r'\%').replace('_',r'\_').replace('#',r'\#')
def cite_note(note):
 note=tex(note)
 def repl(m):
  raw=m[0];sid=re.search(r'3\.[1-6]-[SRE]\d+',raw)[0]
  return r'\href{'+lookup[sid]+'}{'+raw+'}' if sid in lookup else raw
 return re.sub(r'\[3\.[1-6]-[SRE]\d+[^]]*\]',repl,note)
sections={1:(31,'行政区划'),8:(32,'企业'),15:(33,'基金会'),20:(34,'开源项目'),34:(35,'新势力'),38:(36,'开源模型')}
chunks=[];changes=[]
for n in sorted(E):
 title,before,after=E[n];p=plates[n]
 if n in [12,13,14]:p['caption']={12:'图3-12　全球与中国所选企业的月度位次矩阵',13:'图3-13　全球所选企业历史位次：完整数值矩阵',14:'图3-14　中国所选企业历史位次：完整数值矩阵'}[n]
 c=['\\clearpage']
 if n in sections:
  sec,name=sections[n];c += [r'\SetRegion{3.'+str(sec)[1]+' '+name+r'}{violet}{}',r'\phantomsection\label{ch3-sec'+str(sec)+'}',r'\pdfbookmark[1]{'+tex(title)+'}{sec'+str(sec)+'}',r'\section*{'+tex(title)+'}',r'\noindent\includegraphics[width=\linewidth]{figures/new/nav_'+str(sec)+r'.pdf}\par\vspace{3pt}']
 else:c += [r'\pdfbookmark[2]{'+tex(title)+'}{figure'+str(n)+'}',r'\subsection*{'+tex(title)+'}']
 note=cite_note(N[n])
 if n==16:
  monthly=next((R/'sources/s3.3/GOSD_2026_3.3_v0.2/data').glob('fig-3-3-1*.csv'))
  note=note.replace(lookup['3.3-R1'],base+monthly.name)
 c += [tex(before),'',r'\plate{'+p['figure']+'}{'+p['caption']+'}{'+note+'}','',tex(after)]
 if n==31:c += [r'\clearpage\phantomsection\label{ch3-portraits}',r'\pdfbookmark[2]{完整项目画像：PyTorch与OpenHarmony}{portraits}',r'\includepdf[pages=-,fitpaper=true,pagecommand={\thispagestyle{empty}}]{atlas/atlas.pdf}']
 chunks.append('\n'.join(c));changes.append({'figure_number':n,**p,'title':title,'before':before,'after':after,'new_note':N[n]})
(R/'content/chapter3_body.tex').write_text('\n\n'.join(chunks))
(R/'provenance/source_ledger.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2))
(R/'review/editorial_map.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2))
assert len(E)==38 and set(E)==set(plates)
print('38 figure-led units; source records:',len(ledger),'linked:',len(lookup))
